    for op in ('>','>='):
        P=(lambda f1,f2,op:(lambda *x:f1(*x)>f2(*x)) if op=='>' else (lambda *x:f1(*x)>=f2(*x)))(f1,f2,op)
        t=run(which,P,Bt,Wt)
